package com.e02.rootconsole;
import java.util.*;
public class TestFeatures {
 private static void require(boolean b){if(!b)throw new AssertionError();}
 public static void main(String[] args){require(NetworkState.sameSubnet("192.0.2.10","192.0.2.20",24));require(!NetworkState.sameSubnet("192.0.2.10","192.0.3.20",24));List<NetworkState.Address> nets=Arrays.asList(new NetworkState.Address("192.0.2.10","ap0",(short)24),new NetworkState.Address("198.51.100.10","wlan0",(short)24));require(NetworkState.choose(nets,"192.0.2.20").iface.equals("ap0"));require(NetworkState.choose(nets,"203.0.113.20")==null);require(NetworkState.choose(Arrays.asList(nets.get(0),new NetworkState.Address("192.0.2.11","wlan1",(short)24)),"192.0.2.20")==null);require(UpdatePolicy.newer(8,7)&&!UpdatePolicy.newer(8,8)&&!UpdatePolicy.newer(7,8));for(String proxy:UpdatePolicy.ROUTES){String url=UpdatePolicy.url(proxy,UpdatePolicy.MANIFEST);require(proxy.isEmpty()?url.equals(UpdatePolicy.MANIFEST):url.startsWith(proxy+"/https://"));}require(UpdatePolicy.normalize("example.com/").equals("https://example.com"));for(String bad:new String[]{"http://example.com","https://user:token@example.com","https://example.com/?key=1","https://example.com/path"}){try{UpdatePolicy.normalize(bad);throw new AssertionError("Bad proxy accepted");}catch(IllegalArgumentException expected){}}try{UpdatePolicy.url("","https://evil.example/update.apk");throw new AssertionError();}catch(IllegalArgumentException expected){}String client=RemoteConfig.client("example.com",7000,"token","1234567890123456","192.0.2.10",true,true),visitor=RemoteConfig.visitor("example.com",7000,"token","1234567890123456",true,true);require(client.contains("type = \"stcp\"")&&!client.contains("remotePort"));require(visitor.contains("bindPort = 8556")&&visitor.contains("bindAddr = \"127.0.0.1\""));try{RemoteConfig.port("70000");throw new AssertionError();}catch(IllegalArgumentException expected){}System.out.println("Network selection, update policy, private remote config PASS");}
}
